import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const SignInModal = () => {
    const { user } = useAuth();
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        // If user is logged in, don't show the modal
        if (user) return;

        // Check if user has already dismissed it this session
        const hasDismissed = sessionStorage.getItem('hasDismissedSignIn');
        if (!hasDismissed) {
            // Show after a slight delay so it doesn't instantly block the user
            const timer = setTimeout(() => {
                setIsVisible(true);
            }, 3000);

            return () => clearTimeout(timer);
        }
    }, [user]);

    const handleClose = () => {
        setIsVisible(false);
        sessionStorage.setItem('hasDismissedSignIn', 'true');
    };

    if (!isVisible) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm font-display p-4">
            <div className="bg-white w-full max-w-[400px] p-8 relative shadow-2xl animate-fade-in-up">

                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-xs uppercase tracking-[0.1em] font-medium text-black">Sign In</h2>
                    <button 
                        onClick={handleClose} 
                        className="text-gray-900 hover:text-gray-500 transition-colors"
                        aria-label="Close"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>

                {/* Body Content */}
                <p className="text-[13px] text-gray-900 mb-6 font-medium">
                    Sign in with your email or sign up to become an Bindass member.
                </p>

                <form onSubmit={(e) => { e.preventDefault(); /* Hook up to auth later */ }}>
                    <div className="mb-6">
                        <label className="block text-[11px] text-red-600 mb-2">
                            Email <span aria-hidden="true">*</span>
                        </label>
                        <input 
                            type="email" 
                            required
                            placeholder="Email"
                            className="w-full border border-gray-300 p-3 text-sm focus:outline-none focus:border-black transition-colors placeholder-gray-400"
                        />
                    </div>

                    <button 
                        type="submit"
                        className="w-full bg-black text-white py-4 text-xs font-bold tracking-widest uppercase hover:bg-gray-800 transition-colors mb-4"
                    >
                        Continue
                    </button>
                </form>

                {/* Security and Linking */}
                <div className="flex justify-center items-center gap-2 mb-6">
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-3.5 h-3.5 text-gray-700">
                      <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z" />
                    </svg>
                    <span className="text-[11px] text-gray-700">All data is kept secure</span>
                </div>

                <div className="text-center">
                    <a href="/membership" className="text-xs uppercase tracking-widest font-bold text-black border-b border-black pb-0.5 hover:text-gray-600 hover:border-gray-600 transition-colors inline-block">
                        BINDASS MEMBERSHIP
                    </a>
                </div>

            </div>
        </div>
    );
};

export default SignInModal;
